/**
 * @param {string} s
 * @return {string[]}
 */
var ambiguousCoordinates = function(s) {
    const digits = s.slice(1, -1);
    const n = digits.length;
    const res = [];

    function makeParts(str) {
        const out = [];
        const len = str.length;

        if (len === 1) {
            out.push(str);
            return out;
        }

        // integer form
        if (str[0] !== '0') out.push(str);

        // decimal forms
        for (let i = 1; i < len; i++) {
            const left = str.slice(0, i);
            const right = str.slice(i);

            // left part can't have leading zeros unless it's exactly "0"
            if (left.length > 1 && left[0] === '0') break;
            // right part can't end with zero
            if (right[right.length - 1] === '0') continue;

            out.push(left + '.' + right);
        }

        return out;
    }

    for (let i = 1; i < n; i++) {
        const left = digits.slice(0, i);
        const right = digits.slice(i);

        const leftOptions = makeParts(left);
        const rightOptions = makeParts(right);

        for (const a of leftOptions) {
            for (const b of rightOptions) {
                res.push(`(${a}, ${b})`);
            }
        }
    }

    return res;
};
