/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length, n = grid[0].length;
    const total = m * n;
    const top = total;

    const parent = new Int32Array(total + 1);
    const size = new Int32Array(total + 1);
    for (let i = 0; i <= total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (size[ra] < size[rb]) {
            const t = ra; ra = rb; rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    const copy = grid.map(row => row.slice());
    for (const [r, c] of hits) {
        if (copy[r][c] === 1) copy[r][c] = 0;
    }

    const idx = (r, c) => r * n + c;

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (copy[r][c] !== 1) continue;
            const id = idx(r, c);
            if (r === 0) union(id, top);
            if (r > 0 && copy[r - 1][c] === 1) union(id, idx(r - 1, c));
            if (c > 0 && copy[r][c - 1] === 1) union(id, idx(r, c - 1));
        }
    }

    const res = new Array(hits.length);
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];

    for (let k = hits.length - 1; k >= 0; k--) {
        const r = hits[k][0], c = hits[k][1];
        if (grid[r][c] === 0) {
            res[k] = 0;
            continue;
        }

        const before = size[find(top)];
        const id = idx(r, c);
        copy[r][c] = 1;

        if (r === 0) union(id, top);
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && copy[nr][nc] === 1) {
                union(id, idx(nr, nc));
            }
        }

        const after = size[find(top)];
        res[k] = Math.max(0, after - before - 1);
    }

    return res;
};
