/**
 * @param {number[]} arr
 * @return {number}
 */
var numFactoredBinaryTrees = function(arr) {
    const MOD = 1000000007;
    arr.sort((a, b) => a - b);
    const n = arr.length;
    const dp = new Array(n).fill(1);
    const index = new Map();
    for (let i = 0; i < n; i++) index.set(arr[i], i);

    for (let i = 0; i < n; i++) {
        const x = arr[i];
        for (let j = 0; j < i; j++) {
            const a = arr[j];
            if (x % a !== 0) continue;
            const b = x / a;
            const k = index.get(b);
            if (k === undefined) continue;
            dp[i] = (dp[i] + (dp[j] * dp[k]) % MOD) % MOD;
        }
    }

    let ans = 0;
    for (let i = 0; i < n; i++) ans = (ans + dp[i]) % MOD;
    return ans;
};
